import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052895000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-3-1-2026-08-18" tabindex="-1">[0.3.1] - 2026-08-18 <a class="header-anchor" href="#_0-3-1-2026-08-18" aria-label="Permalink to “[0.3.1] - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li><li><code>docs/.vitepress/config.ts</code> pointed <code>og:image</code> at <code>/og.png</code>, which did not exist — the documentation site had no link preview at all. The file is generated now.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The four rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview, instead of being drawn by hand.</li></ul><h2 id="_0-3-0-2026-08-16" tabindex="-1">[0.3.0] - 2026-08-16 <a class="header-anchor" href="#_0-3-0-2026-08-16" aria-label="Permalink to “[0.3.0] - 2026-08-16”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>Dockerfile</code> (multi-stage, non-root, stdio entrypoint) and <code>.dockerignore</code>, so registries that build and introspect the server in a container no longer have to guess a build.</li><li>Multi-arch container images (amd64/arm64) at <code>ghcr.io/ni-c/hetzner-dns-mcp</code>, published from CI with an SBOM and max-mode build provenance and scanned with Trivy on every push and pull request. <code>server.json</code> lists the image as an OCI package, so the MCP registry offers it alongside the npm package.</li><li><code>HETZNER_READ_ONLY=true</code> registers only the seven read-only tools. The write tools are not registered at all rather than rejected when called, so there is no code path from a write request to the API.</li><li>Documentation site at <a href="https://hetzner-dns-mcp.ni-c.de" target="_blank" rel="noreferrer">hetzner-dns-mcp.ni-c.de</a> with a guide, the full tool reference and the security model.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>A missing <code>HETZNER_API_TOKEN</code> no longer exits at startup. The server completes the MCP handshake and lists its tools without credentials; the token is required when a tool actually calls the API, which then fails with the same setup instructions as before. Base URL validation still exits, since a bad base URL can leak the token.</li><li><strong>Breaking:</strong> the <code>confirm</code> boolean is gone. Destructive tools now take an optional <code>confirmToken</code> instead — see below. Callers that passed <code>confirm: true</code> will be refused and handed a token to call again with.</li><li><code>engines.node</code> raised to <code>&gt;=22</code>; Node 20 is end-of-life and is no longer in the CI matrix. The container has been on Node 24 all along.</li><li>Published source maps embed their sources, since only <code>dist/</code> is shipped and the maps previously pointed at a <code>src/</code> that is not in the tarball.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li><p><strong>Destructive tools require a server-issued confirmation token.</strong> Every irreversible tool refuses its first call and returns a random, single-use token with a five-minute lifetime; a second call must repeat the identical arguments and pass it. For <code>set_records</code>, <code>remove_records</code>, <code>import_zonefile</code> and <code>change_primary_nameservers</code> the token is bound to a SHA-256 fingerprint of the payload, so a confirmation for one record list cannot write a different one.</p><p>The previous <code>confirm</code> boolean was a value the model set itself, while the refusal messages pasted the current RRSet contents back as raw API JSON. Together that was a self-approving loop: an instruction hidden in a TXT record value or a zone-file comment arrived verbatim in the very message asking for confirmation. A token cannot be produced that way, because it only ever exists in a previous result from this server.</p></li><li><p>Removing protection now counts as destructive. <code>change_zone_protection</code> and <code>change_rrset_protection</code> had no guard at all, so unprotecting a zone and deleting it was two uninterrupted calls; disabling protection is now gated exactly like the deletion it enables, while enabling it stays immediate.</p></li><li><p>Confirmation messages no longer quote anything read back from the API. They report record counts and TTLs only.</p></li><li><p>API responses are wrapped in an <code>&lt;untrusted-data&gt;</code> envelope, keys matching <code>tsig_key</code>, <code>token</code>, <code>secret</code>, <code>password</code> or <code>credential</code> are redacted, single values are truncated at 4 000 characters and whole results at 200 000.</p></li><li><p>Upstream error bodies are truncated at 2 000 characters and HTML error pages — a reverse proxy or WAF in front of the API — are dropped entirely instead of being pasted into the model&#39;s context.</p></li><li><p><code>HETZNER_API_TOKEN</code> and <code>HETZNER_API_BASE_URL</code> are deleted from the environment once read, so a later crash report or diagnostic dump cannot expose them. An unparseable base URL is no longer echoed back, since it can contain a <code>user:token@</code> part.</p></li><li><p><code>mcp-publisher</code> is pinned to a release and verified against its SHA-256 before it runs. It was fetched from <code>/releases/latest</code> unverified, in a job holding <code>id-token: write</code>.</p></li><li><p>The runtime image no longer ships npm, npx or corepack; they are never invoked there, but their vendored dependencies kept appearing in scans.</p></li><li><p>CI additionally runs CodeQL and a Trivy scan of the image for both architectures.</p></li></ul><h2 id="_0-2-3-2026-08-13" tabindex="-1">[0.2.3] - 2026-08-13 <a class="header-anchor" href="#_0-2-3-2026-08-13" aria-label="Permalink to “[0.2.3] - 2026-08-13”">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>zod updated to v4 (the MCP SDK supports <code>^3.25 || ^4.0</code>); <code>z.record()</code> now uses the explicit two-argument form.</li><li>Dev dependencies updated: TypeScript 6 (<code>@types/node</code> is listed explicitly in the tsconfig <code>types</code> field, as TS 6 no longer auto-includes <code>@types</code> packages), <code>@eslint/js</code> 10 (matching ESLint 10).</li></ul><h2 id="_0-2-2-2026-08-11" tabindex="-1">[0.2.2] - 2026-08-11 <a class="header-anchor" href="#_0-2-2-2026-08-11" aria-label="Permalink to “[0.2.2] - 2026-08-11”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Listed in the official <a href="https://registry.modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP Registry</a> as <code>io.github.ni-c/hetzner-dns-mcp</code>; the release workflow publishes registry updates automatically via GitHub OIDC (<code>server.json</code>, <code>mcpName</code> field).</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Dev dependencies updated: vitest 4 (+ matching <code>@vitest/coverage-v8</code>), ESLint 10, <code>@types/node</code> 26; GitHub Actions pins bumped to current major versions. Coverage thresholds rebased to vitest 4&#39;s stricter AST-based measurement.</li></ul><h2 id="_0-2-1-2026-08-11" tabindex="-1">[0.2.1] - 2026-08-11 <a class="header-anchor" href="#_0-2-1-2026-08-11" aria-label="Permalink to “[0.2.1] - 2026-08-11”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li>Release workflow: pushing a <code>vX.Y.Z</code> tag runs the tests, publishes to npm via Trusted Publishing (OIDC, with provenance) and creates a GitHub release with the notes from this changelog.</li><li>CI: test matrix extended to Node 24, coverage report (thresholds enforced, uploaded as artifact), weekly <code>npm audit</code> job, Dependabot for npm packages and pinned GitHub Actions.</li></ul><h2 id="_0-2-0-2026-08-11" tabindex="-1">[0.2.0] - 2026-08-11 <a class="header-anchor" href="#_0-2-0-2026-08-11" aria-label="Permalink to “[0.2.0] - 2026-08-11”">​</a></h2><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Renamed the package from <code>mcp-hetzner-dns</code> to <code>hetzner-dns-mcp</code>.</li><li><code>set_records</code>, <code>remove_records</code> and <code>change_primary_nameservers</code> now require <code>confirm=true</code> (like the other destructive tools) and report the current state when refusing; <code>change_primary_nameservers</code> is annotated as destructive.</li></ul><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>HETZNER_API_BASE_URL</code> is validated: https only (http allowed for localhost), URLs with embedded credentials are rejected, and a warning is printed for non-default hosts, since the API token is sent there.</li><li><code>zone</code> and RRSet <code>name</code> parameters are restricted to a safe character set and <code>.</code>/<code>..</code> are rejected, preventing URL path traversal out of the intended API endpoints.</li><li>API requests no longer follow redirects and time out after 30 seconds.</li><li>Fatal errors log only the error message instead of the full stack trace.</li><li>CI: workflow token restricted to <code>contents: read</code>, actions pinned to commit SHAs.</li></ul><h2 id="_0-1-0-2026-08-06" tabindex="-1">[0.1.0] - 2026-08-06 <a class="header-anchor" href="#_0-1-0-2026-08-06" aria-label="Permalink to “[0.1.0] - 2026-08-06”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial release targeting the DNS endpoints of the Hetzner Cloud API (<code>api.hetzner.cloud/v1</code>, Bearer token authentication). The legacy DNS API (<code>dns.hetzner.com</code>) is not supported.</li><li>Zone tools: <code>list_zones</code>, <code>get_zone</code>, <code>create_zone</code>, <code>update_zone</code>, <code>delete_zone</code> (guarded by a <code>confirm</code> parameter), <code>export_zonefile</code>, <code>import_zonefile</code> (guarded by a <code>confirm</code> parameter), <code>change_zone_ttl</code>, <code>change_zone_protection</code>, <code>change_primary_nameservers</code>.</li><li>RRSet tools: <code>list_rrsets</code>, <code>get_rrset</code>, <code>create_rrset</code>, <code>update_rrset</code>, <code>delete_rrset</code> (guarded by a <code>confirm</code> parameter), <code>set_records</code>, <code>add_records</code>, <code>remove_records</code>, <code>change_rrset_ttl</code>, <code>change_rrset_protection</code>.</li><li>Action tools: <code>list_zone_actions</code>, <code>get_zone_action</code>.</li><li>Configuration via <code>HETZNER_API_TOKEN</code>, optional <code>HETZNER_API_BASE_URL</code>.</li></ul>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};